// Triage Cases is the doctor's work queue: find, claim and open cases. The clinical decision
// itself stays on the Approval Desk (ApprovalsPage).
import { useCallback, useEffect, useMemo, useState } from 'react'

import '../../styles/triage-queue.css'
import { Pagination } from '../../components/shared/Pagination'
import { ErrorState, LoadingState } from '../../components/shared/ViewState'
import {
  apiClient,
  type AvailableCaseDto,
  type PagedResult,
  type TriageCaseDto,
} from '../../services/apiClient'
import { CasePreview } from './CasePreview'
import {
  QUEUE_TABS,
  actionFor,
  caseReference,
  filterAndSort,
  formatSubmitted,
  mergeQueue,
  priorityTone,
  queueCounts,
  statusLabel,
  statusTone,
  type QueueCase,
  type QueueSort,
  type QueueTab,
} from './triageQueue'

const PAGE_SIZE = 8
const FETCH_SIZE = 100
const MAX_FETCH_PAGES = 10

type Notice = { tone: 'success' | 'warning'; text: string }

async function fetchAll<T>(url: string): Promise<T[]> {
  const items: T[] = []
  for (let page = 1; page <= MAX_FETCH_PAGES; page += 1) {
    const { data } = await apiClient.get<PagedResult<T>>(url, { params: { page, pageSize: FETCH_SIZE } })
    items.push(...(data.items ?? []))
    if (page >= (data.totalPages ?? 1)) break
  }
  return items
}

const httpStatus = (error: unknown) => (error as { response?: { status?: number } })?.response?.status

const emptyCopy: Record<QueueTab, string> = {
  available: 'No cases are waiting to be claimed right now.',
  mine: 'You have no active cases. Claim one from Available.',
  completed: 'Cases you have decided appear here while your access remains active.',
  emergency: 'There are no emergency referrals.',
}

export function CasesPage() {
  const [cases, setCases] = useState<QueueCase[]>([])
  const [status, setStatus] = useState<'loading' | 'ready' | 'error'>('loading')
  const [refreshing, setRefreshing] = useState(false)
  const [tab, setTab] = useState<QueueTab>('available')
  const [priorityFilter, setPriorityFilter] = useState('ALL')
  const [statusFilter, setStatusFilter] = useState('ALL')
  const [sort, setSort] = useState<QueueSort>('oldest')
  const [search, setSearch] = useState('')
  const [page, setPage] = useState(1)
  const [selectedId, setSelectedId] = useState('')
  const [previewOpen, setPreviewOpen] = useState(false)
  const [filtersOpen, setFiltersOpen] = useState(false)
  const [claimingId, setClaimingId] = useState('')
  const [notice, setNotice] = useState<Notice | null>(null)

  const loadCases = useCallback(async (initial: boolean) => {
    if (initial) setStatus('loading')
    else setRefreshing(true)
    try {
      const [assigned, pool] = await Promise.all([
        fetchAll<TriageCaseDto>('/doctors/me/cases'),
        fetchAll<AvailableCaseDto>('/doctors/case-pool'),
      ])
      setCases(mergeQueue(assigned, pool))
      setStatus('ready')
    } catch {
      if (initial) setStatus('error')
      else setNotice({ tone: 'warning', text: 'The queue could not be refreshed. Showing the last loaded cases.' })
    } finally {
      setRefreshing(false)
    }
  }, [])

  useEffect(() => {
    void loadCases(true)
  }, [loadCases])

  const counts = useMemo(() => queueCounts(cases), [cases])
  const tabCount: Record<QueueTab, number> = {
    available: counts.available,
    mine: counts.mine,
    completed: counts.completed,
    emergency: counts.emergency,
  }
  const visible = useMemo(
    () => filterAndSort(cases, { tab, priority: priorityFilter, status: statusFilter, search, sort }),
    [cases, tab, priorityFilter, statusFilter, search, sort],
  )
  const totalPages = Math.max(1, Math.ceil(visible.length / PAGE_SIZE))
  const currentPage = Math.min(page, totalPages)
  const pageItems = visible.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE)
  const selected = cases.find((item) => item.id === selectedId) ?? null
  const statusOptions = useMemo(() => {
    const inTab = filterAndSort(cases, { tab, priority: 'ALL', status: 'ALL', search: '', sort: 'oldest' })
    return [...new Map(inTab.map((item) => [item.status, statusLabel(item)])).entries()]
  }, [cases, tab])

  function openTab(next: QueueTab, nextStatus = 'ALL') {
    setTab(next)
    setStatusFilter(nextStatus)
    setPage(1)
  }

  function select(item: QueueCase) {
    setSelectedId(item.id)
    setPreviewOpen(true)
  }

  const closePreview = useCallback(() => setPreviewOpen(false), [])

  async function claim(item: QueueCase) {
    if (claimingId) return
    setClaimingId(item.id)
    setNotice(null)
    const acknowledging = item.status === 'Escalated'
    try {
      await apiClient.post(`/triage-cases/${item.id}/claim`)
      setNotice({
        tone: 'success',
        text: acknowledging
          ? `Emergency referral ${caseReference(item)} acknowledged.`
          : `Case ${caseReference(item)} is now assigned to you. Open it from My Cases.`,
      })
    } catch (error) {
      const code = httpStatus(error)
      setNotice({
        tone: 'warning',
        text:
          code === 409
            ? 'Another doctor claimed this case first. The queue has been refreshed.'
            : code === 403 || code === 404
              ? 'This case is no longer available to you. The queue has been refreshed.'
              : 'The case was not claimed. Nothing was changed. Try again.',
      })
    } finally {
      // The list is always re-read so the queue shows server truth, not an assumed transition.
      await loadCases(false)
      setClaimingId('')
    }
  }

  const summary: { label: string; value: number; tone: string; onOpen: () => void }[] = [
    { label: 'Available Cases', value: counts.available, tone: 'primary', onOpen: () => openTab('available') },
    { label: 'My Active Cases', value: counts.mine, tone: 'primary', onOpen: () => openTab('mine') },
    { label: 'Awaiting Review', value: counts.awaitingReview, tone: 'warning', onOpen: () => openTab('mine') },
    { label: 'Emergency Referrals', value: counts.emergency, tone: 'danger', onOpen: () => openTab('emergency') },
  ]

  return (
    <div className="care-workspace triage-queue">
      <header className="care-header triage-queue__header">
        <div>
          <h1>Triage Case Management</h1>
          <p>Manage incoming requests and cases assigned to you.</p>
        </div>
        <div className="triage-queue__tools">
          <input
            type="search"
            className="triage-search"
            placeholder="Search case reference"
            aria-label="Search by case reference"
            value={search}
            onChange={(event) => {
              setSearch(event.target.value)
              setPage(1)
            }}
          />
          <button
            type="button"
            className="button button--secondary"
            disabled={refreshing || status === 'loading'}
            onClick={() => void loadCases(status !== 'ready')}
          >
            {refreshing ? 'Refreshing…' : 'Refresh'}
          </button>
        </div>
      </header>

      {notice ? (
        <p role="status" className={`care-note care-note--${notice.tone}`}>
          {notice.text}
        </p>
      ) : null}

      {status === 'loading' ? (
        <LoadingState label="Loading triage cases" />
      ) : status === 'error' ? (
        <ErrorState message="The triage case queue could not be loaded." onRetry={() => void loadCases(true)} />
      ) : (
        <>
          <section className="triage-summary" aria-label="Queue summary">
            {summary.map((card) => (
              <button
                key={card.label}
                type="button"
                className={`triage-summary__card triage-summary__card--${card.tone}`}
                onClick={card.onOpen}
              >
                <strong>{String(card.value).padStart(2, '0')}</strong>
                <span>{card.label}</span>
              </button>
            ))}
          </section>

          <div className="triage-tabs" role="tablist" aria-label="Case queues">
            {QUEUE_TABS.map((entry) => (
              <button
                key={entry.id}
                type="button"
                role="tab"
                id={`triage-tab-${entry.id}`}
                aria-selected={tab === entry.id}
                aria-controls="triage-tabpanel"
                className={`triage-tab${entry.id === 'emergency' ? ' triage-tab--emergency' : ''}`}
                onClick={() => openTab(entry.id)}
              >
                {entry.label}
                <span className="triage-tab__count">{tabCount[entry.id]}</span>
              </button>
            ))}
          </div>

          <button
            type="button"
            className="button button--secondary triage-filter-toggle"
            aria-expanded={filtersOpen}
            aria-controls="triage-filters"
            onClick={() => setFiltersOpen((current) => !current)}
          >
            Filter and sort
          </button>
          <div id="triage-filters" className={`triage-filters${filtersOpen ? ' triage-filters--open' : ''}`}>
            <label className="field">
              <span>Priority</span>
              <select
                value={priorityFilter}
                onChange={(event) => {
                  setPriorityFilter(event.target.value)
                  setPage(1)
                }}
              >
                <option value="ALL">All priorities</option>
                {['Routine', 'Priority', 'Emergency'].map((value) => (
                  <option key={value}>{value}</option>
                ))}
              </select>
            </label>
            <label className="field">
              <span>Status</span>
              <select
                value={statusFilter}
                onChange={(event) => {
                  setStatusFilter(event.target.value)
                  setPage(1)
                }}
              >
                <option value="ALL">All statuses</option>
                {statusOptions.map(([value, label]) => (
                  <option key={value} value={value}>
                    {label}
                  </option>
                ))}
              </select>
            </label>
            <label className="field">
              <span>Sort</span>
              <select value={sort} onChange={(event) => setSort(event.target.value as QueueSort)}>
                <option value="oldest">Oldest first</option>
                <option value="newest">Newest first</option>
                <option value="priority">Priority first</option>
              </select>
            </label>
          </div>

          <div className="triage-layout">
            <section
              key={tab}
              id="triage-tabpanel"
              role="tabpanel"
              aria-labelledby={`triage-tab-${tab}`}
              className="triage-list"
            >
              {pageItems.length === 0 ? (
                <div className="care-panel triage-empty">
                  <h2>No matching cases</h2>
                  <p className="care-caption">
                    {visible.length === 0 && tabCount[tab] > 0
                      ? 'No cases match the current search or filters.'
                      : emptyCopy[tab]}
                  </p>
                </div>
              ) : (
                pageItems.map((item) => {
                  const action = actionFor(item)
                  const claimAction = action.kind === 'claim' || action.kind === 'acknowledge'
                  const busy = claimingId === item.id
                  return (
                    <article
                      key={item.id}
                      className={`triage-card${selectedId === item.id ? ' triage-card--selected' : ''}${
                        item.status === 'Escalated' ? ' triage-card--emergency' : ''
                      }`}
                    >
                      <div className="triage-card__top">
                        <div>
                          <h2>{item.memberDisplayName || `Case ${caseReference(item)}`}</h2>
                          <p className="care-caption">
                            {item.memberDisplayName
                              ? `${item.familyName ? `${item.familyName} · ` : ''}Case ${caseReference(item)} · `
                              : ''}
                            Submitted {formatSubmitted(item.createdAt)}
                            {item.claimable ? ' · Shared review pool' : ''}
                          </p>
                        </div>
                        <div className="triage-tags">
                          <span className={`status-badge status-badge--${priorityTone(item.priority)}`}>
                            {item.priority}
                          </span>
                          <span className={`status-badge status-badge--${statusTone(item)}`}>
                            {item.status === 'Escalated' ? <span aria-hidden="true">⚠ </span> : null}
                            {statusLabel(item)}
                          </span>
                        </div>
                      </div>
                      <div className="triage-card__foot">
                        <p className="care-caption">
                          {item.mine
                            ? 'Open the case to see the submitted complaint.'
                            : 'Details available after authorized access.'}
                        </p>
                        <div className="triage-card__actions">
                          <button
                            type="button"
                            className="button button--secondary"
                            aria-pressed={selectedId === item.id}
                            aria-label={`${item.mine ? 'Open case' : 'Preview case'} ${caseReference(item)}`}
                            onClick={() => select(item)}
                          >
                            {item.mine ? 'Open Case' : 'Preview'}
                          </button>
                          {claimAction ? (
                            <button
                              type="button"
                              className={`button button--primary${
                                action.kind === 'acknowledge' ? ' triage-button--emergency' : ''
                              }`}
                              disabled={claimingId !== ''}
                              aria-label={`${action.label} ${caseReference(item)}`}
                              onClick={() => void claim(item)}
                            >
                              {busy ? 'Working…' : action.label}
                            </button>
                          ) : null}
                        </div>
                      </div>
                    </article>
                  )
                })
              )}
              {visible.length > PAGE_SIZE ? (
                <Pagination currentPage={currentPage} totalPages={totalPages} onPageChange={setPage} />
              ) : null}
            </section>

            <CasePreview
              item={selected}
              open={previewOpen}
              busy={claimingId !== ''}
              onClose={closePreview}
              onClaim={(item) => void claim(item)}
            />
            {previewOpen && selected ? (
              <button type="button" className="triage-backdrop" aria-label="Close case preview" onClick={closePreview} />
            ) : null}
          </div>
        </>
      )}
    </div>
  )
}
